-- =====================================================================
-- Portfolio 1 — seed_data.sql
-- Static reference data: branches, capacities for 730 days of history plus
-- the next 60 days,
-- cake types, flavours, plus a small set of representative customers
-- (the bulk 50k+ orders are generated by bulk_generator.sql).
--
--   sudo runuser -u postgres -- psql -d sweetcrust -f seed_data.sql
-- =====================================================================

-- ---- 4 branches -----------------------------------------------------
INSERT INTO branch(name, city, address) VALUES
    ('SweetCrust Surulere', 'Lagos', '14 Adeniran Ogunsanya St, Surulere, Lagos'),
    ('SweetCrust Lekki',    'Lagos', '75A Admiralty Way, Lekki Phase 1, Lagos'),
    ('SweetCrust Ikeja',    'Lagos', '29 Allen Avenue, Ikeja, Lagos'),
    ('SweetCrust Bodija',   'Ibadan','Adeoye Road, Bodija, Ibadan');

-- ---- Per-branch daily capacity (units/day). Lekki and Ikeja bigger. ---
-- Capacities are seeded for every day from 730 days ago to today + 60 days
-- so the bulk generator (history + next 14 days) and the P3 demos never hit
-- a missing daily_capacity row.
INSERT INTO daily_capacity (branch_id, cap_date, max_units)
SELECT b.branch_id,
       CURRENT_DATE + g,
       CASE b.name
            WHEN 'SweetCrust Surulere' THEN 25
            WHEN 'SweetCrust Lekki'    THEN 40
            WHEN 'SweetCrust Ikeja'    THEN 35
            WHEN 'SweetCrust Bodija'   THEN 20
       END
FROM   branch b
CROSS JOIN generate_series(-730, 60) AS g;

